	// From pair (sa,sb), we sum over all possible next pair states consistent with equal letter.
	// That gives us a linear recurrence over length m with matrix size up to (1+sum len)^2 <= (1+40)^2=1681.

	// Implement this.

	// Build single-hint states
	type HState struct {
		w int
		p int
	}
	var hstates []HState
	idx := make(map[[2]int]int)
	// state 0: (0,0)
	hstates = append(hstates, HState{w: 0, p: 0})
	idx[[2]int{0, 0}] = 0
	for i := 0; i < n; i++ {
		for p := 0; p < ws[i].l; p++ {
			key := [2]int{i + 1, p}
			idx[key] = len(hstates)
			hstates = append(hstates, HState{w: i + 1, p: p})
		}
	}
	hsz := len(hstates)

	// For each hstate, list possible emissions and next states.
	// Emission: letter byte; we store as int 0..25
	type Edge struct {
		ch  int
		nxt int
	}
	hEdges := make([][]Edge, hsz)
	for sid, st := range hstates {
		if st.w == 0 {
			// between words: choose any word, emit its first letter
			for i := 0; i < n; i++ {
				ch := int(ws[i].s[0] - 'a')
				nxt := idx[[2]int{i + 1, 0}]
				hEdges[sid] = append(hEdges[sid], Edge{ch: ch, nxt: nxt})
			}
		} else {
			i := st.w - 1
			p := st.p
			ch := int(ws[i].s[p] - 'a')
			var nxt int
			if p+1 < ws[i].l {
				nxt = idx[[2]int{st.w, p + 1}]
			} else {
				nxt = idx[[2]int{0, 0}]
			}
			hEdges[sid] = append(hEdges[sid], Edge{ch: ch, nxt: nxt})
		}
	}

	// Build product automaton states: pair of hstates
	type PState struct {
		a int
		b int
	}
	pIdx := make(map[[2]int]int)
	var pstates []PState
	for i := 0; i < hsz; i++ {
		for j := 0; j < hsz; j++ {
			key := [2]int{i, j}
			pIdx[key] = len(pstates)
			pstates = append(pstates, PState{a: i, b: j})
		}
	}
	psz := len(pstates)

	// Build transition matrix
	mat := newMatrix(psz)
	for pid, ps := range pstates {
		edgesA := hEdges[ps.a]
		edgesB := hEdges[ps.b]
		// For each pair of edges with same letter
		for _, ea := range edgesA {
			for _, eb := range edgesB {
				if ea.ch == eb.ch {
					nxtKey := [2]int{ea.nxt, eb.nxt}
					nid := pIdx[nxtKey]
					mat.a[pid][nid]++
					if mat.a[pid][nid] >= MOD {
						mat.a[pid][nid] -= MOD
					}
				}
			}
		}
	}

	// Initial vector: at position 0, both hints are between words: state (0,0)
	start := pIdx[[2]int{0, 0}]
	// We need number of length-m strings: paths of length m in this automaton.
	// Each step corresponds to one column emitting a letter.
	if m == 0 {
		// length 0 chainword: no letters; hints must be empty sequences; only 1 instance
		fmt.Println(1)
		return
	}
	matPowM := matPow(mat, m)

	// initial vector has 1 at start
	var ans int64 = 0
	// Any final state is allowed
	for j := 0; j < psz; j++ {
		ans += matPowM.a[start][j]
		if ans >= MOD {
			ans -= MOD
		}
	}
	fmt.Println(ans % MOD)
